-- PR5.19 read-only verification after APPLY. Exactly ten checks should be true.
select 'three_target_products_still_published' check_name,count(*)=3 passed from software_discovery.products where slug in ('affine','appflowy','anytype') and status='published'
union all select 'three_reviewed_ai_optional_claims',count(*)=3 and bool_and(c.value_boolean and c.verification_status='verified' and c.last_verified_at='2026-10-12T00:00:00Z' and c.confidence=case when p.slug='affine' then .90 else .85 end) from software_discovery.product_attributes c join software_discovery.products p on p.id=c.product_id join software_discovery.attributes a on a.id=c.attribute_id where p.slug in ('affine','appflowy','anytype') and a.slug='ai-optional'
union all select 'six_new_dated_sources',count(*)=6 and bool_and(retrieved_at='2026-10-12T00:00:00Z') from software_discovery.evidence_sources where seed_key like 'notion-ai-%-2026-10-12'
union all select 'six_new_ai_evidence_links',count(*)=6 and bool_and((p.slug='affine' and s.seed_key in ('notion-ai-affine-guide-2026-10-12','notion-ai-affine-ai-2026-10-12')) or (p.slug='appflowy' and s.seed_key='notion-ai-appflowy-docs-2026-10-12') or (p.slug='anytype' and s.seed_key in ('notion-ai-anytype-welcome-2026-10-12','notion-ai-anytype-choice-2026-10-12','notion-ai-anytype-agents-2026-10-12'))) from software_discovery.product_attribute_evidence l join software_discovery.products p on p.id=l.product_id join software_discovery.attributes a on a.id=l.attribute_id join software_discovery.claim_evidence e on e.id=l.claim_evidence_id join software_discovery.evidence_sources s on s.id=e.evidence_source_id where a.slug='ai-optional' and s.seed_key like 'notion-ai-%-2026-10-12'
union all select 'historical_ai_evidence_retained',not exists(select 1 from (values ('appflowy','appflowy-welcome-2026-10-05'),('affine','affine-pricing-2026-10-05')) expected(product_slug,source_key) where not exists(select 1 from software_discovery.product_attribute_evidence l join software_discovery.products p on p.id=l.product_id join software_discovery.attributes a on a.id=l.attribute_id join software_discovery.claim_evidence e on e.id=l.claim_evidence_id join software_discovery.evidence_sources s on s.id=e.evidence_source_id where p.slug=expected.product_slug and a.slug='ai-optional' and s.seed_key=expected.source_key))
union all select 'three_bounded_notion_anchors_retained',count(*)=3 and bool_and(c.verification_status='verified' and c.relationship_scope='personal-offline-note-object-organization' and length(trim(c.scope_description))>0) from software_discovery.product_anchors c join software_discovery.products p on p.id=c.product_id join software_discovery.anchors a on a.id=c.anchor_id where p.slug in ('affine','appflowy','anytype') and a.slug='notion' and c.relationship_type='alternative'
union all select 'ten_products_three_routes_preserved',(select count(*)=10 from software_discovery.products where slug in ('obsidian','things','omnifocus','2do','affine','anytype','appflowy','gimp','krita','paint-net') and status='published') and (select count(*)=3 from software_discovery.escape_routes where slug in ('todoist-alternatives-with-a-one-time-purchase','offline-notion-alternatives','photoshop-alternatives-without-a-subscription') and status='published' and editorially_approved)
union all select 'no_ai_route_remains_unpublished',not exists(select 1 from software_discovery.escape_routes where slug='notion-alternatives-without-ai' and (status<>'draft' or editorially_approved))
union all select 'three_public_rpc_ai_projections',bool_and(software_discovery.product_discovery_page(slug)->>'status'='published' and exists(select 1 from jsonb_array_elements(software_discovery.product_discovery_page(slug)->'attributes') a where a->>'slug'='ai-optional' and a->>'value'='true' and a->>'verificationStatus'='verified')) from (values ('affine'),('appflowy'),('anytype')) p(slug)
union all select 'anon_private_evidence_boundary',has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') and not has_table_privilege('anon','software_discovery.claim_evidence','SELECT');
